    private void item(LinearLayout parent,String title,String summary,Runnable action){MaterialCardView card=Ui.card(a);LinearLayout row=Ui.padded(a);row.addView(Ui.text(a,title+"  ›",16,true));row.addView(Ui.help(a,summary));card.addView(row);card.setOnClickListener(v->action.run());parent.addView(card);}
    private void toggle(LinearLayout form,String label,String hint,boolean value,java.util.function.Consumer<Boolean> onChange){MaterialSwitch control=new MaterialSwitch(a);control.setText(label);control.setChecked(value);control.setPadding(0,Ui.dp(a,10),0,Ui.dp(a,10));form.addView(control);if(!hint.isEmpty())form.addView(Ui.help(a,hint));control.setOnCheckedChangeListener((v,on)->onChange.accept(on));}
    public void root(LinearLayout form){item(form,"全部安排与搜索","长任务 · 子任务 · 提醒 · 年历 · 类型",()->PlanHub.show(a));item(form,"任务类型","三级分类、归档与合并；随事项同步",()->TaskTypes.show(a));item(form,"桌面小组件","今日安排、勾选完成、天气与快速新建",this::widget);item(form,"外观与主题","系统主题 · 深色 · 动态强调色 · 壁纸",this::appearance);item(form,"位置与天气",p.getString("city","授权后自动获取大致位置"),this::weather);item(form,"扩展与存储","可选OCR · 导入 · 专注 · 项目看板",()->ExtensionHub.show(a));item(form,"通知收集","应用 · 短信 · 群聊 · 全部内容 · 正则",this::capture);item(form,"Agent模型配置","统一厂商、模型、API地址与密钥",this::api);item(form,"数据与同步","文件导入导出，可选云端与局域网",this::sync);item(form,"版本更新","日栖 "+version()+" · MIT",this::updates);item(form,"开源组件与许可","节假日 / jsoup · MIT；原生Markdown / ICS / 裁剪",this::licenses);}
    public void appearance(){LinearLayout form=a.fullPage("外观与主题",a::home);form.addView(Ui.text(a,"主题",18,true));ChipGroup group=new ChipGroup(a);group.setSingleSelection(true);group.setSelectionRequired(true);String[] labels={"跟随系统","浅色","深色"},values={"system","light","dark"};for(int i=0;i<3;i++){String value=values[i];Chip chip=new Chip(a);chip.setText(labels[i]);chip.setCheckable(true);chip.setChecked(p.getString("theme","system").equals(value));chip.setOnClickListener(v->{p.edit().putString("theme",value).apply();DayFlowApp.applyTheme(value);AgendaWidget.refresh(a);});group.addView(chip);}form.addView(group);
        toggle(form,"紧凑列表与表格","减少卡片和表格留白，操作区域仍至少48dp。",p.getBoolean("compact_ui",false),on->{p.edit().putBoolean("compact_ui",on).apply();a.recreate();});
        toggle(form,"使用系统动态强调色","Android 12 及以上跟随系统壁纸配色；其他版本使用日栖配色。",p.getBoolean("dynamic_color",true),on->{p.edit().putBoolean("dynamic_color",on).apply();a.recreate();});
        ThemeColors.settings(a,form);form.addView(Ui.button(a,"选择自定义壁纸",false,()->a.pickFile(104,"image/*")));form.addView(Ui.button(a,"恢复默认背景",false,()->{new File(a.getFilesDir(),"wallpaper.jpg").delete();p.edit().remove("wallpaper_seed").apply();AgendaWidget.refresh(a);a.recreate();}));
        toggle(form,"动态流光","仅在前台运行，省电模式暂停。",p.getBoolean("motion",false),on->{p.edit().putBoolean("motion",on).apply();a.refreshBackdrop();});toggle(form,"背景模糊","Android 12 及以上可用。",p.getBoolean("blur",true),on->{p.edit().putBoolean("blur",on).apply();a.refreshBackdrop();});toggle(form,"左右滑动切换页面","今天左滑进入周预览；输入和裁剪区域不触发切页。",p.getBoolean("swipe",true),on->p.edit().putBoolean("swipe",on).apply());form.addView(Ui.text(a,"背景不透明度",14,true));Slider slider=new Slider(a);slider.setValueFrom(65);slider.setValueTo(100);slider.setStepSize(1);slider.setValue(p.getInt("opacity",86));slider.addOnChangeListener((s,value,user)->{if(user){p.edit().putInt("opacity",Math.round(value)).apply();a.refreshBackdrop();}});form.addView(slider);
    }
    public void widget(){LinearLayout form=a.fullPage("桌面小组件",a::home);form.addView(Ui.text(a,"不用打开应用，也能掌握今天",23,true));form.addView(Ui.help(a,"今日安排、天气、勾选完成和快速新建。支持桌面缩放，并适配深色主题与系统强调色。"));MaterialCardView preview=Ui.card(a);View widget=a.getLayoutInflater().inflate(R.layout.widget,null);preview.addView(widget);form.addView(preview);form.addView(Ui.button(a,"添加到桌面",true,()->{AppWidgetManager manager=AppWidgetManager.getInstance(a);if(manager.isRequestPinAppWidgetSupported()){manager.requestPinAppWidget(new ComponentName(a,AgendaWidget.class),null,null);a.message("请在桌面启动器中确认添加");}else a.message("请长按桌面 → 小组件 → 日栖");}));toggle(form,"小组件显示待确认收集箱","显示待确认数量及最新一条内容，点击进入确认。",p.getBoolean("widget_inbox",true),on->{p.edit().putBoolean("widget_inbox",on).apply();AgendaWidget.refresh(a);});form.addView(Ui.button(a,"刷新已添加的小组件",false,()->{AgendaWidget.refresh(a);a.message("已刷新");}));}
    public void weather(){LinearLayout form=a.fullPage("位置与天气",a::home);form.addView(Ui.text(a,p.getString("city","当前位置"),23,true));form.addView(Ui.text(a,p.getString("weather_cache","尚未获取天气"),30,true));form.addView(Ui.help(a,"只在前台按需获取大致位置，不在后台持续定位。拒绝授权也可搜索城市。天气由 Open-Meteo 提供。"));form.addView(Ui.button(a,"使用当前位置获取天气",true,()->{p.edit().putBoolean("auto_location",true).apply();a.locationWeather.request();}));toggle(form,"自动更新位置天气","打开应用时，缓存超过6小时才刷新。",p.getBoolean("auto_location",false),on->{p.edit().putBoolean("auto_location",on).apply();if(on)a.locationWeather.request();});form.addView(Ui.button(a,"搜索并选择城市",false,this::citySearch));form.addView(Ui.help(a,"最近更新 "+p.getString("weather_time","").replace("T"," ")));}
    private void citySearch(){LinearLayout form=a.fullPage("选择城市",this::weather);TextInputEditText query=Ui.field(a,form,"城市名称，例如北京、上海","",false);form.addView(Ui.help(a,"搜索词会发送给 Open-Meteo，不需要位置权限。"));form.addView(Ui.button(a,"搜索城市",true,()->{String name=query.getText().toString().trim();if(name.isEmpty()){query.setError("请填写城市名称");return;}final JSONArray[] result={null};a.job(()->{JSONObject response=Network.request("https://geocoding-api.open-meteo.com/v1/search?name="+java.net.URLEncoder.encode(name,"UTF-8")+"&count=8&language=zh&format=json",null,"");result[0]=response.optJSONArray("results");if(result[0]==null)result[0]=new JSONArray();return result[0].length()==0?"没有找到城市，请尝试完整名称":"请选择城市";},()->{if(result[0]==null)return;LinearLayout list=a.fullPage("选择城市",this::citySearch);for(int i=0;i<result[0].length();i++){JSONObject city=result[0].optJSONObject(i);String label=city.optString("name")+" · "+city.optString("admin1")+" · "+city.optString("country");item(list,city.optString("name"),label,()->a.job(()->{String value=PlannerServices.weather(a,city.getDouble("latitude"),city.getDouble("longitude"),city.optString("name"));p.edit().putBoolean("auto_location",false).apply();return value;},this::weather));}});}));}
    private void capture(){GroupCaptureSettings.show(a);}
