    private void useBackend(String backend){try{boolean windows=backend.equals("taskflow");if(p.getString(windows?"tf_address":"server","").isEmpty()||Secrets.get(a,windows?"tf_token":"token").isEmpty())throw new Exception(windows?"请先连接 Windows":"请先登录 DayFlow 服务器");p.edit().putString("sync_backend",backend).putBoolean("sync_auto",true).apply();SyncJob.configure(a);sync();a.message("已切换同步服务，本地内容保留");}catch(Exception e){a.message(e.getMessage());}}
    public void sync(){LinearLayout form=a.fullPage("数据与同步",a::home);form.addView(Ui.help(a,"当前同步服务："+(p.getString("sync_backend","dayflow").equals("taskflow")?"TaskFlow Windows":"DayFlow 云端／局域网")));form.addView(Ui.button(a,"连接 TaskFlow Windows 端",true,()->TaskFlowSettings.show(a)));if(!p.getString("server","").isEmpty())form.addView(Ui.button(a,"使用已登录的 DayFlow 服务",false,()->useBackend("dayflow")));if(!p.getString("tf_address","").isEmpty())form.addView(Ui.button(a,"使用已连接的 TaskFlow Windows",false,()->useBackend("taskflow")));form.addView(Ui.help(a,"文字及图片笔记、日程、每日待办、课程、收集箱、阶段任务与完成/删除状态都使用同一套同步。文件或云端均保留事项 ID，冲突保留副本。本地使用无需账号。"));toggle(form,"自动同步全部内容","连接服务器账号后，修改按系统网络条件同步，另有每15分钟系统调度。省电策略可能延后；也可立即同步。",p.getBoolean("sync_auto",false),on->{p.edit().putBoolean("sync_auto",on).apply();SyncJob.configure(a);});form.addView(Ui.help(a,"同步状态："+p.getString("sync_message","尚未同步")+"\n上次成功："+p.getString("sync_last","暂无")));form.addView(Ui.help(a,"API Key、登录凭据、通知授权、壁纸与天气位置是设备配置，不包含在同步文件中。"));form.addView(Ui.button(a,"导出同步文件",true,()->a.startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json").putExtra(Intent.EXTRA_TITLE,"dayflow-"+LocalDate.now()+".dayflow"),101)));form.addView(Ui.button(a,"合并导入同步文件",false,()->a.pickFile(102,"*/*")));form.addView(Ui.button(a,"云端 / 局域网账号",false,this::account));form.addView(Ui.button(a,"立即同步",false,()->a.job(()->Network.sync(a),null)));form.addView(Ui.button(a,"查看与处理同步冲突",false,()->SyncConflicts.show(a,0)));form.addView(Ui.button(a,"退出服务器账号",false,()->a.job(()->{return TaskFlowSettings.logout(a);},null)));}
    private void account(){LinearLayout form=a.fullPage("服务器账号",this::sync);TextInputEditText server=Ui.field(a,form,"服务器地址（域名或IP，可含端口）",p.getString("server",""),false),user=Ui.field(a,form,"用户名",p.getString("username",""),false),password=Ui.field(a,form,"密码","",false),invite=Ui.field(a,form,"邀请码（注册时选填）","",false);password.setInputType(129);MaterialSwitch register=new MaterialSwitch(a);register.setText("注册新账号");form.addView(register);TextView status=Ui.help(a,"默认端口8765。域名默认 HTTPS，局域网 IP 可用 HTTP。请填服务端地址，不能填 GitHub 项目网址。登录失败时保留本页输入。" );form.addView(status);
        form.addView(Ui.button(a,"检查服务器连接",false,()->{String address=server.getText().toString();status.setText("正在连接服务器…");a.job(()->Network.checkServer(address),()->status.setText("服务器连接正常，可继续登录"),message->status.setText("连接失败："+message));}));
        form.addView(Ui.button(a,"连接并登录",true,()->{String address=server.getText().toString(),username=user.getText().toString(),pass=password.getText().toString(),code=invite.getText().toString();boolean create=register.isChecked();status.setText("正在登录…");a.job(()->PlannerServices.login(a,address,username,pass,code,create),this::sync,message->status.setText("登录失败："+message+"\n输入内容已保留，请修改后重试。"));}));}

    private String version(){try{return a.getPackageManager().getPackageInfo(a.getPackageName(),0).versionName;}catch(Exception ignored){return "未知";}}
    public void updates(){LinearLayout form=a.fullPage("版本更新",a::home);form.addView(Ui.text(a,"日栖 "+version(),26,true));form.addView(Ui.help(a,"今天清单 · 独立表格编辑 · 笔记 · 全部内容同步"));form.addView(Ui.button(a,"检查更新",true,a::checkUpdates));TextInputEditText feed=Ui.field(a,form,"更新清单 URL",Updates.feed(a),false);form.addView(Ui.button(a,"保存更新源",false,()->{try{p.edit().putString("update_feed",Network.endpoint(feed.getText().toString(),true)).apply();a.message("已保存更新源");}catch(Exception e){a.message(e.getMessage());}}));toggle(form,"定期检查并通知","每12小时按系统调度检查，不会静默安装。",p.getBoolean("update_auto",false),on->{p.edit().putBoolean("update_auto",on).apply();Updates.configureJob(a);if(on)a.notificationPermission();});}
    private void licenses(){LinearLayout page=a.fullPage("开源组件与许可",a::home);page.addView(Ui.help(a,"日栖原创代码采用 MIT。复用的组件保留各自许可证。"));String[] labels={"lunar-java · MIT","jsoup · MIT","节假日数据 · MIT","biweekly · BSD 2-Clause","Material / AndroidX · Apache 2.0","完整第三方声明（含插件）"},files={"lunar-java-MIT.txt","jsoup-MIT.txt","holiday-cn-MIT.txt","biweekly-BSD.txt","Apache-2.0.txt","THIRD_PARTY_NOTICES.md"};for(int i=0;i<labels.length;i++){String label=labels[i],file=files[i];page.addView(Ui.button(a,label,false,()->{try(java.io.InputStream input=a.getAssets().open("licenses/"+file)){String text=Network.read(input,32768);LinearLayout form=a.fullPage(label,this::licenses);TextView body=Ui.text(a,text,13,false);body.setTextIsSelectable(true);form.addView(body);}catch(Exception e){a.message(e.getMessage());}}));}}
    public void showUpdate(JSONObject info){LinearLayout form=a.fullPage("发现新版本 "+info.optString("version"),this::updates);form.addView(Ui.text(a,info.optString("notes"),16,false));form.addView(Ui.help(a,"大小 "+(info.optLong("size")/1024)+" KB。清单验证签名，安装包验证 SHA-256，由系统确认安装。"));String found=null;try{found=Updates.cached(a,info);}catch(Exception ignored){}final String cached=found;if(cached!=null)form.addView(Ui.help(a,"安装包已缓存并通过校验，本次不会重复下载。"));form.addView(Ui.button(a,cached==null?"下载并安装":"安装已下载的更新",true,()->{if(cached!=null){try{Updates.install(a,cached);}catch(Exception e){a.message(e.getMessage());}return;}a.job(()->{String path=Updates.download(a,info);a.runOnUiThread(()->{if(!a.isDestroyed())try{Updates.install(a,path);}catch(Exception e){a.message(e.getMessage());}});return "更新包已验证";},null);}));}
